// 💬 Fast 1-Click WhatsApp & Facebook Native Chrome Tabs Handler
document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('a[href*="whatsapp.com"], a[href*="facebook.com"]').forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const targetUrl = link.getAttribute('href');
            if (targetUrl && chrome?.tabs?.create) {
                chrome.tabs.create({ url: targetUrl });
            } else if (targetUrl) {
                window.open(targetUrl, '_blank');
            }
        });
    });
});


// ============================================================================
// ⚡ LIGHTNING-FAST ULTRA-RESPONSIVE PROMPT MANAGER (0ms Batch Rendering)
// ============================================================================
(() => {
  'use strict';

  let localPrompts = [];
  let currentFilter = 'all';
  let searchQuery = '';

  const elPromptsContainer = document.getElementById('prompts-container');
  const elCounter = document.getElementById('prompt-counter');
  const elCountAll = document.getElementById('count-all');
  const elCountQueued = document.getElementById('count-queued');
  const elCountDone = document.getElementById('count-done');
  const elSearchInput = document.getElementById('input-search-prompts');
  const elFilterPills = document.querySelectorAll('.filter-pill');
  const elFileInput = document.getElementById('file-upload-prompts');
  const elBtnUpload = document.getElementById('btn-trigger-upload');
  const elTextarea = document.getElementById('textarea-quick-prompts');
  const elBtnAddBulk = document.getElementById('btn-add-bulk-prompts');
  const elBtnReset = document.getElementById('btn-reset-progress');
  const elBtnClear = document.getElementById('btn-clear-prompts');
  const elBtnReload = document.getElementById('btn-reload-extension');

  if (elBtnReload) {
    elBtnReload.addEventListener('click', () => {
      elBtnReload.textContent = '🔄 Reloading...';
      chrome.runtime.sendMessage({ type: 'RELOAD_EXTENSION' });
      setTimeout(() => window.location.reload(), 500);
    });
  }

  function escapeHtml(str) {
    return String(str || '').replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function parsePromptsFromText(text) {
    if (!text || typeof text !== 'string') return [];
    const normalized = text.replace(/\r\n?/g, '\n').trim();
    if (!normalized) return [];

    // If text contains double newlines (paragraphs), parse by paragraph
    if (/\n(?:[^\S\n]*\n)+/.test(normalized)) {
      const paragraphs = normalized.split(/\n(?:[^\S\n]*\n)+/)
        .map(p => p.trim())
        .filter(Boolean);

      return paragraphs.map((p, idx) => {
        let title = '';
        let promptText = p;
        if (p.includes(',') && !p.includes('\n') && !p.startsWith('"')) {
          const parts = p.split(',');
          if (parts.length >= 2 && parts[0].length < 35) {
            title = parts[0].trim();
            promptText = parts.slice(1).join(',').trim();
          }
        }
        return {
          prompt: promptText,
          title: title || `Prompt #${idx + 1}`,
          done: false
        };
      });
    }

    const lines = normalized.split('\n');
    const results = [];

    for (let i = 0; i < lines.length; i++) {
      let line = lines[i].trim();
      if (!line) continue;

      // Skip CSV header if present
      if (i === 0 && (/^prompt,title/i.test(line) || /^id,prompt/i.test(line) || /^#\s*,/i.test(line))) {
        continue;
      }

      let title = '';
      let promptText = line;

      // Handle CSV comma/tab separation if present
      if (line.includes(',') && !line.startsWith('"')) {
        const parts = line.split(',');
        if (parts.length >= 2 && parts[0].length < 35) {
          title = parts[0].trim();
          promptText = parts.slice(1).join(',').trim();
        }
      } else if (line.startsWith('"') && line.endsWith('"')) {
        promptText = line.substring(1, line.length - 1).replace(/""/g, '"').trim();
      }

      if (promptText) {
        results.push({
          prompt: promptText,
          title: title || '',
          done: false
        });
      }
    }
    return results;
  }

  function renderPromptsUltraFast() {
    if (!elPromptsContainer) return;

    const total = localPrompts.length;
    const doneCount = localPrompts.filter(p => p.done).length;
    const queuedCount = total - doneCount;

    if (elCounter) elCounter.textContent = String(total);
    if (elCountAll) elCountAll.textContent = String(total);
    if (elCountQueued) elCountQueued.textContent = String(queuedCount);
    if (elCountDone) elCountDone.textContent = String(doneCount);

    if (total === 0) {
      elPromptsContainer.innerHTML = '<div class="empty-state">No prompts loaded yet. Upload a CSV/TXT or paste prompts above.</div>';
      return;
    }

    const filtered = localPrompts.map((p, idx) => ({ ...p, originalIdx: idx })).filter(item => {
      if (currentFilter === 'queued' && item.done) return false;
      if (currentFilter === 'done' && !item.done) return false;
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const pText = (item.prompt || item.text || '').toLowerCase();
        const tText = (item.title || '').toLowerCase();
        return pText.includes(q) || tText.includes(q);
      }
      return true;
    });

    if (filtered.length === 0) {
      elPromptsContainer.innerHTML = '<div class="empty-state">No matching prompts found.</div>';
      return;
    }

    // High-speed DocumentFragment batching — 1 single DOM paint
    const fragment = document.createDocumentFragment();

    for (let i = 0; i < filtered.length; i++) {
      const item = filtered[i];
      const origIdx = item.originalIdx;
      const numStr = String(origIdx + 1).padStart(2, '0');

      const card = document.createElement('div');
      card.className = 'prompt-card' + (item.done ? ' prompt-done' : '');
      card.dataset.index = String(origIdx);

      const titleText = item.title || ('Prompt #' + numStr);
      const promptStr = item.prompt || item.text || '';
      const previewText = promptStr.replace(/\r?\n/g, ' ');

      card.innerHTML = `
        <button class="btn-toggle-done" data-action="toggle" title="Toggle Done status">${item.done ? '✅' : '⚪'}</button>
        <span class="prompt-num-badge" data-action="paste" title="Click to paste into active Dola chat">#${numStr}</span>
        <div class="prompt-info-column" data-action="paste" title="Click to paste into active Dola chat">
          <span class="prompt-title-text">${escapeHtml(titleText)}</span>
          <span class="prompt-text-preview">${escapeHtml(previewText)}</span>
        </div>
        <button class="btn-prompt-paste" data-action="paste" title="Paste prompt into active Dola chat">Paste</button>
        <button class="btn-prompt-del" data-action="delete" title="Delete prompt">✕</button>
      `;

      fragment.appendChild(card);
    }

    elPromptsContainer.replaceChildren(fragment);
  }

  function savePromptsToStorage() {
    chrome.storage.local.set({ 'ctb_saved_prompts': localPrompts });
  }

  function pastePromptToTab(item, origIdx) {
    if (!item) return;
    const promptStr = item.prompt || item.text || '';
    if (!promptStr) return;
    const numStr = String(origIdx + 1).padStart(2, '0');
    chrome.tabs.query({ active: true, currentWindow: true }, tabs => {
      if (tabs[0]?.id) {
        chrome.tabs.sendMessage(tabs[0].id, {
          action: 'paste_prompt_to_page',
          prompt: promptStr,
          promptNumber: origIdx + 1,
          promptTitle: item.title || ('Prompt #' + numStr)
        }, () => {
          if (chrome.runtime.lastError) {}
        });
      }
    });
  }

  // Fast Delegated Event Listener for all Prompt actions
  if (elPromptsContainer) {
    elPromptsContainer.addEventListener('click', e => {
      const target = e.target.closest('[data-action]');
      if (!target) return;

      const card = target.closest('.prompt-card');
      if (!card) return;

      const origIdx = parseInt(card.dataset.index, 10);
      if (isNaN(origIdx) || !localPrompts[origIdx]) return;

      const action = target.dataset.action;

      if (action === 'paste') {
        pastePromptToTab(localPrompts[origIdx], origIdx);
        localPrompts[origIdx].done = true;
        renderPromptsUltraFast();
        savePromptsToStorage();
      } else if (action === 'toggle') {
        localPrompts[origIdx].done = !localPrompts[origIdx].done;
        renderPromptsUltraFast();
        savePromptsToStorage();
      } else if (action === 'delete') {
        localPrompts.splice(origIdx, 1);
        renderPromptsUltraFast();
        savePromptsToStorage();
      }
    });
  }

  // Fast File Upload (CSV/TXT)
  if (elBtnUpload && elFileInput) {
    elBtnUpload.addEventListener('click', () => elFileInput.click());
    elFileInput.addEventListener('change', e => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = ev => {
        const text = ev.target?.result;
        if (text && typeof text === 'string') {
          const parsed = parsePromptsFromText(text);
          if (parsed.length > 0) {
            localPrompts = parsed;
            renderPromptsUltraFast(); // Instant render (0ms delay)
            savePromptsToStorage();
          }
        }
        elFileInput.value = '';
      };
      reader.readAsText(file);
    });
  }

  // Live Detected Prompts Counter
  const elDetectedCount = document.getElementById('detected-prompts-count');
  if (elTextarea && elDetectedCount) {
    elTextarea.addEventListener('input', () => {
      const val = elTextarea.value.trim();
      const detected = val ? parsePromptsFromText(val).length : 0;
      elDetectedCount.textContent = String(detected);
    });
  }

  // Fast Add Bulk Prompts Textarea
  if (elBtnAddBulk && elTextarea) {
    elBtnAddBulk.addEventListener('click', () => {
      const text = elTextarea.value.trim();
      if (!text) return;

      const parsed = parsePromptsFromText(text);
      if (parsed.length > 0) {
        localPrompts = localPrompts.concat(parsed);
        renderPromptsUltraFast(); // Instant render (0ms delay)
        savePromptsToStorage();
        elTextarea.value = '';
        if (elDetectedCount) elDetectedCount.textContent = '0';
      }
    });
  }

  // Fast Reset Done Statuses
  if (elBtnReset) {
    elBtnReset.addEventListener('click', () => {
      localPrompts.forEach(p => { p.done = false; });
      renderPromptsUltraFast();
      savePromptsToStorage();
    });
  }

  // Fast Clear All Prompts
  if (elBtnClear) {
    elBtnClear.addEventListener('click', () => {
      if (confirm('Clear all prompts?')) {
        localPrompts = [];
        renderPromptsUltraFast();
        savePromptsToStorage();
      }
    });
  }

  // Fast Live Search
  if (elSearchInput) {
    elSearchInput.addEventListener('input', e => {
      searchQuery = (e.target.value || '').trim();
      renderPromptsUltraFast();
    });
  }

  // Fast Filter Pills
  if (elFilterPills) {
    elFilterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        elFilterPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        currentFilter = pill.dataset.filter || 'all';
        renderPromptsUltraFast();
      });
    });
  }

  // Initial Instant Load from Storage
  chrome.storage.local.get(['ctb_saved_prompts'], data => {
    if (Array.isArray(data.ctb_saved_prompts)) {
      localPrompts = data.ctb_saved_prompts;
      renderPromptsUltraFast();
    }
  });

  console.log('[ChannaTheBrand Pro] ⚡ Lightning-Fast Prompt Engine Active.');
})();

