// ============================================================================
// ⚡ 10-TAB MULTI-ACCOUNT PARALLEL FARM & BATCH ROTATION CONTROLLER
// ============================================================================
(() => {
  let currentFarmBatchIndex = 0;
  let cachedTotalBatches = 1;
  let currentFarmTabCount = 10;

  const elFarmAccCount = document.getElementById('farm-acc-count');
  const elFarmPromptCount = document.getElementById('farm-prompt-count');
  const elFarmTotalBatches = document.getElementById('farm-total-batches');
  const elFarmBatchBadge = document.getElementById('farm-batch-badge');
  const elBtnLaunchFarm = document.getElementById('btn-launch-farm');
  const elBtnNextBatch = document.getElementById('btn-next-batch');
  const elLabelLaunchTitle = document.getElementById('label-launch-title');
  const elLabelLaunchBatch = document.getElementById('label-launch-batch');
  const elLabelNextBatch = document.getElementById('label-next-batch');
  const elFarmStatusText = document.getElementById('farm-status-text');
  const elBtnCloseFarm = document.getElementById('btn-close-farm');

  // Tab Speed Presets & Custom Input
  const elPresetEco = document.getElementById('farm-preset-eco');
  const elPresetTurbo = document.getElementById('farm-preset-turbo');
  const elPresetBeast = document.getElementById('farm-preset-beast');
  const elCustomTabCount = document.getElementById('farm-custom-tab-count');

  function applySpeedPresetUI(count, save = true) {
    const num = Math.max(1, Math.min(50, parseInt(count, 10) || 10));
    currentFarmTabCount = num;
    if (elCustomTabCount) elCustomTabCount.value = num;

    // Eco (3)
    if (elPresetEco) {
      if (num === 3) {
        elPresetEco.style.background = 'rgba(16, 185, 129, 0.35)';
        elPresetEco.style.border = '1px solid #10b981';
        elPresetEco.style.boxShadow = '0 0 6px rgba(16, 185, 129, 0.4)';
      } else {
        elPresetEco.style.background = 'rgba(16, 185, 129, 0.12)';
        elPresetEco.style.border = '1px solid rgba(16, 185, 129, 0.4)';
        elPresetEco.style.boxShadow = 'none';
      }
    }

    // Turbo (5)
    if (elPresetTurbo) {
      if (num === 5) {
        elPresetTurbo.style.background = 'rgba(245, 158, 11, 0.35)';
        elPresetTurbo.style.border = '1px solid #f59e0b';
        elPresetTurbo.style.boxShadow = '0 0 6px rgba(245, 158, 11, 0.4)';
      } else {
        elPresetTurbo.style.background = 'rgba(245, 158, 11, 0.12)';
        elPresetTurbo.style.border = '1px solid rgba(245, 158, 11, 0.4)';
        elPresetTurbo.style.boxShadow = 'none';
      }
    }

    // Beast (10)
    if (elPresetBeast) {
      if (num === 10) {
        elPresetBeast.style.background = 'rgba(239, 68, 68, 0.35)';
        elPresetBeast.style.border = '1px solid #ef4444';
        elPresetBeast.style.boxShadow = '0 0 6px rgba(239, 68, 68, 0.4)';
      } else {
        elPresetBeast.style.background = 'rgba(239, 68, 68, 0.12)';
        elPresetBeast.style.border = '1px solid rgba(239, 68, 68, 0.4)';
        elPresetBeast.style.boxShadow = 'none';
      }
    }

    // Custom highlight
    if (elCustomTabCount) {
      if (![3, 5, 10].includes(num)) {
        elCustomTabCount.style.border = '1px solid #38bdf8';
        elCustomTabCount.style.boxShadow = '0 0 6px rgba(56, 189, 248, 0.35)';
      } else {
        elCustomTabCount.style.border = '1px solid #a855f7';
        elCustomTabCount.style.boxShadow = 'none';
      }
    }

    if (save) {
      chrome.storage.local.set({ farm_parallel_tab_count: num });
    }

    updateFarmDashboard();
  }

  // Load saved tab count or default to 10
  chrome.storage.local.get(['farm_parallel_tab_count'], (res) => {
    const saved = parseInt(res?.farm_parallel_tab_count, 10);
    if (saved && saved >= 1 && saved <= 50) {
      applySpeedPresetUI(saved, false);
    } else {
      applySpeedPresetUI(10, false);
    }
  });

  // Attach Preset Handlers
  if (elPresetEco) {
    elPresetEco.addEventListener('click', () => applySpeedPresetUI(3, true));
  }
  if (elPresetTurbo) {
    elPresetTurbo.addEventListener('click', () => applySpeedPresetUI(5, true));
  }
  if (elPresetBeast) {
    elPresetBeast.addEventListener('click', () => applySpeedPresetUI(10, true));
  }
  if (elCustomTabCount) {
    const handleCustom = () => {
      const val = parseInt(elCustomTabCount.value, 10);
      if (!isNaN(val) && val >= 1 && val <= 50) {
        applySpeedPresetUI(val, true);
      }
    };
    elCustomTabCount.addEventListener('input', handleCustom);
    elCustomTabCount.addEventListener('change', handleCustom);
  }

  function updateFarmDashboard() {
    chrome.storage.local.get(['multi_profiles', 'ctb_saved_prompts'], (data) => {
      const multiProfiles = data?.multi_profiles || {};
      const accList = Object.keys(multiProfiles);
      const totalAccounts = accList.length;

      const savedPrompts = Array.isArray(data?.ctb_saved_prompts) ? data.ctb_saved_prompts : [];
      const totalPrompts = savedPrompts.length;

      const batchSize = Math.max(1, currentFarmTabCount);
      cachedTotalBatches = Math.max(1, Math.ceil(totalAccounts / batchSize));
      if (currentFarmBatchIndex >= cachedTotalBatches) {
        currentFarmBatchIndex = 0;
      }

      if (elFarmAccCount) elFarmAccCount.textContent = totalAccounts > 0 ? `${totalAccounts} Loaded` : '0';
      if (elFarmPromptCount) elFarmPromptCount.textContent = totalPrompts > 0 ? `${totalPrompts} Ready` : '0';
      if (elFarmTotalBatches) elFarmTotalBatches.textContent = totalAccounts > 0 ? `${cachedTotalBatches} Batches` : '0';

      const startAccNum = currentFarmBatchIndex * batchSize + 1;
      const endAccNum = Math.min((currentFarmBatchIndex + 1) * batchSize, totalAccounts || batchSize);

      const nextBatchIdx = (currentFarmBatchIndex + 1) % cachedTotalBatches;
      const nextStartAccNum = nextBatchIdx * batchSize + 1;
      const nextEndAccNum = Math.min((nextBatchIdx + 1) * batchSize, totalAccounts || (batchSize * 2));

      const startPNum = currentFarmBatchIndex * batchSize + 1;
      const endPNum = startPNum + batchSize - 1;

      const nextStartPNum = nextBatchIdx * batchSize + 1;
      const nextEndPNum = nextStartPNum + batchSize - 1;

      if (elFarmBatchBadge) {
        elFarmBatchBadge.textContent = totalAccounts > 0
          ? `Batch #${currentFarmBatchIndex + 1} of ${cachedTotalBatches} (${batchSize} Tabs)`
          : `Batch #1 (${batchSize} Tabs)`;
      }

      if (elLabelLaunchTitle) {
        elLabelLaunchTitle.textContent = `🚀 LAUNCH ${batchSize} TABS`;
      }

      if (elLabelLaunchBatch) {
        elLabelLaunchBatch.textContent = totalAccounts > 0
          ? `(Accs ${startAccNum}–${endAccNum} • P${startPNum}–${endPNum})`
          : `(Accounts 1–${batchSize} • ${batchSize} Slots)`;
      }

      if (elLabelNextBatch) {
        elLabelNextBatch.textContent = totalAccounts > 0
          ? `(Accs ${nextStartAccNum}–${nextEndAccNum} ➔ P${nextStartPNum}–${nextEndPNum})`
          : `(Accs ${batchSize + 1}–${batchSize * 2} ➔ P${batchSize + 1}–${batchSize * 2})`;
      }
    });

    // Check if farm tabs are currently open
    chrome.runtime.sendMessage({ type: 'GET_FARM_STATUS' }, (res) => {
      if (chrome.runtime.lastError) return;
      if (res && res.active && res.openTabsCount > 0) {
        if (elBtnCloseFarm) elBtnCloseFarm.style.display = 'inline-block';
        if (elFarmStatusText) {
          elFarmStatusText.textContent = `🟢 Batch #${(res.currentBatchIndex || 0) + 1} running on ${res.openTabsCount} tabs!`;
        }
      } else {
        if (elBtnCloseFarm) elBtnCloseFarm.style.display = 'none';
      }
    });
  }

  // Launch Farm Click
  if (elBtnLaunchFarm) {
    elBtnLaunchFarm.addEventListener('click', () => {
      elBtnLaunchFarm.disabled = true;
      const originalContent = elBtnLaunchFarm.innerHTML;
      elBtnLaunchFarm.innerHTML = `<span style="font-weight: 800;">⏳ SPAWNING...</span><span style="font-size: 8px;">Opening ${currentFarmTabCount} Tabs...</span>`;
      if (elFarmStatusText) elFarmStatusText.textContent = `⏳ Spawning ${currentFarmTabCount} tabs one-by-one (zero RAM surge)...`;

      chrome.runtime.sendMessage({
        type: 'LAUNCH_PARALLEL_FARM_BATCH',
        batchIndex: currentFarmBatchIndex,
        tabCount: currentFarmTabCount
      }, (res) => {
        elBtnLaunchFarm.disabled = false;
        elBtnLaunchFarm.innerHTML = originalContent;

        if (res && res.ok) {
          if (elFarmStatusText) {
            elFarmStatusText.textContent = `🚀 Launched ${res.tabsCount} tabs for Batch #${res.batchIndex + 1}!`;
          }
          if (elBtnCloseFarm) elBtnCloseFarm.style.display = 'inline-block';
          updateFarmDashboard();
        } else {
          if (elFarmStatusText) {
            elFarmStatusText.textContent = `❌ ${res?.error || 'Could not launch farm.'}`;
          }
        }
      });
    });
  }

  // Next Batch Click
  if (elBtnNextBatch) {
    elBtnNextBatch.addEventListener('click', () => {
      currentFarmBatchIndex = (currentFarmBatchIndex + 1) % cachedTotalBatches;
      elBtnNextBatch.disabled = true;
      const originalContent = elBtnNextBatch.innerHTML;
      elBtnNextBatch.innerHTML = `<span style="font-weight: 800;">⏳ SWITCHING...</span><span style="font-size: 8px;">Loading Batch #${currentFarmBatchIndex + 1}...</span>`;
      if (elFarmStatusText) elFarmStatusText.textContent = `⏳ Switching to Batch #${currentFarmBatchIndex + 1} (${currentFarmTabCount} tabs)...`;

      chrome.runtime.sendMessage({
        type: 'SWITCH_PARALLEL_FARM_BATCH',
        batchIndex: currentFarmBatchIndex,
        tabCount: currentFarmTabCount
      }, (res) => {
        elBtnNextBatch.disabled = false;
        elBtnNextBatch.innerHTML = originalContent;

        if (res && res.ok) {
          if (elFarmStatusText) {
            elFarmStatusText.textContent = `⚡ Switched to Batch #${res.batchIndex + 1} (${res.tabsCount} tabs active)!`;
          }
          if (elBtnCloseFarm) elBtnCloseFarm.style.display = 'inline-block';
          updateFarmDashboard();
        } else {
          if (elFarmStatusText) {
            elFarmStatusText.textContent = `❌ ${res?.error || 'Could not switch batch.'}`;
          }
        }
      });
    });
  }

  // Close Farm Tabs Click
  if (elBtnCloseFarm) {
    elBtnCloseFarm.addEventListener('click', () => {
      chrome.runtime.sendMessage({ type: 'CLOSE_FARM_TABS' }, (res) => {
        if (elBtnCloseFarm) elBtnCloseFarm.style.display = 'none';
        if (elFarmStatusText) elFarmStatusText.textContent = `Closed ${res?.closedCount || 0} farm tabs.`;
      });
    });
  }

  // Storage listener to refresh farm stats when accounts or prompts change
  chrome.storage.onChanged.addListener((changes, area) => {
    if (area === 'local' && (changes.multi_profiles || changes.ctb_saved_prompts || changes.farm_parallel_tab_count)) {
      updateFarmDashboard();
    }
  });

  updateFarmDashboard();
  console.log('[ChannaTheBrand Pro] ⚡ Parallel Farm Controller Active.');
})();

// ============================================================================
// ✕ CLOSE ALL DOLA / ACCOUNT TABS BUTTON (Accounts Header)
// ============================================================================
(() => {
  const elBtnCloseAllAccountTabs = document.getElementById('btn-close-all-account-tabs');
  if (!elBtnCloseAllAccountTabs) return;

  elBtnCloseAllAccountTabs.addEventListener('click', async () => {
    try {
      const originalHtml = elBtnCloseAllAccountTabs.innerHTML;
      elBtnCloseAllAccountTabs.disabled = true;
      elBtnCloseAllAccountTabs.innerHTML = '<span style="font-weight: 800;">⏳ Closing...</span>';

      // Query all open Dola / Doubao tabs
      const tabs = await chrome.tabs.query({
        url: ['*://*.dola.com/*', '*://*.doubao.com/*']
      });

      // Clear farm tabs state as well
      chrome.runtime.sendMessage({ type: 'CLOSE_PARALLEL_FARM' });

      if (tabs && tabs.length > 0) {
        const tabIds = tabs.map(t => t.id);
        await chrome.tabs.remove(tabIds);
        elBtnCloseAllAccountTabs.innerHTML = `<span style="font-weight: 800;">✅ ${tabs.length} Closed</span>`;
      } else {
        elBtnCloseAllAccountTabs.innerHTML = '<span style="font-weight: 800;">0 Tabs</span>';
      }

      setTimeout(() => {
        elBtnCloseAllAccountTabs.innerHTML = originalHtml;
        elBtnCloseAllAccountTabs.disabled = false;
      }, 1200);
    } catch (err) {
      console.error('[ChannaTheBrand Pro] Close all tabs error:', err);
      elBtnCloseAllAccountTabs.disabled = false;
    }
  });

  console.log('[ChannaTheBrand Pro] ✕ Close All Account Tabs Controller Active.');
})();

// ============================================================================
// ⚙️ SETTINGS & MAXIMUM CREDIT POINTS LIMIT CONTROLLER (6 or 10 Credits Cap)
// ============================================================================
(() => {
  const elSelCreditLimit = document.getElementById('sel-credit-limit');
  const elSelDuration = document.getElementById('sel-duration');
  const elChkAutoRotate = document.getElementById('chk-autorotate');
  const elChkAutoNext = document.getElementById('chk-autonext');
  const elChkAutoDl = document.getElementById('chk-auto-dl');
  const elChkSafety = document.getElementById('chk-safety');
  const elChkTelemetryShield = document.getElementById('chk-telemetry-shield');
  const elChkFingerprintMask = document.getElementById('chk-fingerprint-mask');
  const elChkOmniChain = document.getElementById('chk-omni-chain');
  const elChkGhostWorker = document.getElementById('chk-ghost-worker');
  const elBadgeGhost = document.getElementById('badge-ghost');
  const elBadgeCredits = document.getElementById('badge-credits');
  const elStatusCreditsSub = document.getElementById('status-credits-sub');

  function updateGhostUI(enabled) {
    if (elBadgeGhost) {
      if (enabled) {
        elBadgeGhost.innerHTML = '<strong>👻 Ghost: ON</strong>';
        elBadgeGhost.style.background = 'rgba(52, 211, 153, 0.15)';
        elBadgeGhost.style.borderColor = 'rgba(52, 211, 153, 0.4)';
        elBadgeGhost.style.color = '#34d399';
        elBadgeGhost.title = 'Ghost Worker: Background Throttling Destroyed (Never Sleep)';
      } else {
        elBadgeGhost.innerHTML = '<strong>👻 Ghost: OFF</strong>';
        elBadgeGhost.style.background = 'rgba(148, 163, 184, 0.15)';
        elBadgeGhost.style.borderColor = 'rgba(148, 163, 184, 0.3)';
        elBadgeGhost.style.color = '#94a3b8';
        elBadgeGhost.title = 'Ghost Worker: Inactive';
      }
    }
    if (elChkGhostWorker) {
      elChkGhostWorker.checked = enabled;
    }
  }

  function updateCreditBadges(cap) {
    const numCap = parseInt(cap, 10) === 10 ? 10 : 6;
    const numVideos = numCap === 10 ? 5 : 3;
    if (elBadgeCredits) {
      elBadgeCredits.textContent = `${numCap} Pts`;
    }
    if (elStatusCreditsSub) {
      elStatusCreditsSub.textContent = `${numCap} Credits Max (${numVideos} Videos)`;
    }
  }

  const elBadgeRatio = document.getElementById('badge-ratio');
  const elBadgeDuration = document.getElementById('badge-duration');
  const durPills = document.querySelectorAll('.dur-pill');
  const ratioPills = document.querySelectorAll('.ratio-pill');

  function updateRatioUI(selectedRatio) {
    const ratio = selectedRatio || '9:16';
    ratioPills.forEach(p => {
      if (p.getAttribute('data-ratio') === ratio) {
        p.classList.add('active');
      } else {
        p.classList.remove('active');
      }
    });
    if (elBadgeRatio) {
      elBadgeRatio.textContent = ratio;
    }
  }

  function updateDurationUI(selectedDur) {
    const dur = String(selectedDur || '30');
    durPills.forEach(p => {
      if (p.getAttribute('data-dur') === dur) {
        p.classList.add('active');
      } else {
        p.classList.remove('active');
      }
    });
    if (elBadgeDuration) {
      elBadgeDuration.textContent = dur === '30' ? '30s HD' : (dur === '60' ? '60s VIP' : `${dur}s`);
    }
    if (elSelDuration) {
      elSelDuration.value = dur;
    }
  }

  // Ratio Pill Click Listeners
  ratioPills.forEach(pill => {
    pill.addEventListener('click', (e) => {
      e.preventDefault();
      const ratio = pill.getAttribute('data-ratio') || '9:16';
      updateRatioUI(ratio);
      chrome.storage.local.set({ 'targetRatio': ratio, 'ratioOverride': ratio }, () => {
        console.log(`[ChannaTheBrand Pro] 📐 Aspect Ratio switched to: ${ratio}`);
        chrome.tabs.query({ url: ['*://*.dola.com/*', '*://dola.com/*', '*://*.doubao.com/*', '*://doubao.com/*', '*://*.seaart.ai/*', '*://seaart.ai/*'] }, (tabs) => {
          if (tabs && tabs.length > 0) {
            tabs.forEach(t => {
              if (t.id) {
                chrome.tabs.sendMessage(t.id, {
                  type: 'SET_RATIO_OVERRIDE',
                  action: 'set_ratio',
                  ratio: ratio
                }).catch(() => {});
              }
            });
          }
        });
      });
    });
  });

  // Duration Pill Click Listeners
  durPills.forEach(pill => {
    pill.addEventListener('click', (e) => {
      e.preventDefault();
      const dur = pill.getAttribute('data-dur') || '30';
      updateDurationUI(dur);
      chrome.storage.local.set({ 'durationOverride': dur }, () => {
        console.log(`[ChannaTheBrand Pro] ⚡ Duration switched to: ${dur}s`);
        chrome.tabs.query({ url: ['*://*.dola.com/*', '*://dola.com/*', '*://*.doubao.com/*', '*://doubao.com/*', '*://*.seaart.ai/*', '*://seaart.ai/*'] }, (tabs) => {
          if (tabs && tabs.length > 0) {
            tabs.forEach(t => {
              if (t.id) {
                chrome.tabs.sendMessage(t.id, {
                  type: 'DURATION_OVERRIDE',
                  action: 'set_duration',
                  duration: dur
                }).catch(() => {});
              }
            });
          }
        });
      });
    });
  });

  // Load initial settings
  chrome.storage.local.get([
    'ctb_max_credits_limit',
    'targetRatio',
    'ratioOverride',
    'durationOverride',
    'ctb_auto_rotate',
    'ctb_auto_next_prompt',
    'zdola_auto_download_config',
    'ctb_safety_sanitizer',
    'ctb_telemetry_shield',
    'ctb_fingerprint_mask',
    'ctb_omni_reference_chaining',
    'ctb_ghost_worker'
  ], (data) => {
    const creditCap = data?.ctb_max_credits_limit || '10';
    if (elSelCreditLimit) elSelCreditLimit.value = creditCap;
    updateCreditBadges(creditCap);

    const ratio = data?.targetRatio || data?.ratioOverride || '9:16';
    updateRatioUI(ratio);

    const dur = data?.durationOverride || '30';
    updateDurationUI(dur);

    if (elChkAutoRotate) {
      elChkAutoRotate.checked = Boolean(data?.ctb_auto_rotate);
    }
    if (elChkAutoNext && data?.ctb_auto_next_prompt !== undefined) {
      elChkAutoNext.checked = Boolean(data.ctb_auto_next_prompt);
    }
    if (elChkAutoDl) {
      elChkAutoDl.checked = data?.zdola_auto_download_config?.autoDownload !== false;
    }
    if (elChkSafety && data?.ctb_safety_sanitizer !== undefined) {
      elChkSafety.checked = Boolean(data.ctb_safety_sanitizer);
    }
    if (elChkTelemetryShield) {
      elChkTelemetryShield.checked = data?.ctb_telemetry_shield !== false;
    }
    if (elChkFingerprintMask) {
      elChkFingerprintMask.checked = data?.ctb_fingerprint_mask !== false;
    }
    if (elChkOmniChain) {
      elChkOmniChain.checked = data?.ctb_omni_reference_chaining !== false;
    }
    const ghostEnabled = data?.ctb_ghost_worker !== false;
    updateGhostUI(ghostEnabled);
  });

  // Credit Limit Change Listener
  if (elSelCreditLimit) {
    elSelCreditLimit.addEventListener('change', (e) => {
      const selectedCap = e.target.value === '10' ? '10' : '6';
      updateCreditBadges(selectedCap);
      chrome.storage.local.set({ 'ctb_max_credits_limit': selectedCap }, () => {
        console.log(`[ChannaTheBrand Pro] 💎 Maximum Credit Points Limit set to: ${selectedCap} Credits`);
        // Broadcast to all active tabs
        chrome.tabs.query({ url: ['*://*.dola.com/*', '*://dola.com/*', '*://*.doubao.com/*', '*://doubao.com/*', '*://*.seaart.ai/*', '*://seaart.ai/*'] }, (tabs) => {
          tabs.forEach(t => {
            if (t.id) {
              chrome.tabs.sendMessage(t.id, {
                type: 'SET_MAX_CREDITS_LIMIT',
                maxCredits: selectedCap
              }).catch(() => {});
            }
          });
        });
      });
    });
  }

  // Duration Setting Listener
  if (elSelDuration) {
    elSelDuration.addEventListener('change', (e) => {
      const dur = e.target.value || '30';
      updateDurationUI(dur);
      chrome.storage.local.set({ 'durationOverride': dur }, () => {
        chrome.tabs.query({ url: ['*://*.dola.com/*', '*://dola.com/*', '*://*.doubao.com/*', '*://doubao.com/*', '*://*.seaart.ai/*', '*://seaart.ai/*'] }, (tabs) => {
          if (tabs && tabs.length > 0) {
            tabs.forEach(t => {
              if (t.id) {
                chrome.tabs.sendMessage(t.id, {
                  type: 'DURATION_OVERRIDE',
                  action: 'set_duration',
                  duration: dur
                }).catch(() => {});
              }
            });
          }
        });
      });
    });
  }

  // Feature Toggles Listeners
  if (elChkAutoRotate) {
    elChkAutoRotate.addEventListener('change', (e) => {
      chrome.storage.local.set({ 'ctb_auto_rotate': e.target.checked });
    });
  }
  if (elChkAutoNext) {
    elChkAutoNext.addEventListener('change', (e) => {
      chrome.storage.local.set({ 'ctb_auto_next_prompt': e.target.checked });
    });
  }
  if (elChkAutoDl) {
    elChkAutoDl.addEventListener('change', (e) => {
      const enabled = e.target.checked;
      chrome.storage.local.get(['zdola_auto_download_config'], (res) => {
        const conf = res?.zdola_auto_download_config || {};
        conf.autoDownload = enabled;
        chrome.storage.local.set({ 'zdola_auto_download_config': conf });
      });
      chrome.runtime.sendMessage({ type: 'TOGGLE_AUTO_DOWNLOAD', enabled }).catch(() => {});
    });
  }
  if (elChkSafety) {
    elChkSafety.addEventListener('change', (e) => {
      chrome.storage.local.set({ 'ctb_safety_sanitizer': e.target.checked });
    });
  }
  if (elChkTelemetryShield) {
    elChkTelemetryShield.addEventListener('change', (e) => {
      const enabled = e.target.checked;
      chrome.storage.local.set({ 'ctb_telemetry_shield': enabled });
      chrome.runtime.sendMessage({ type: 'SET_TELEMETRY_SHIELD', enabled }).catch(() => {});
    });
  }
  if (elChkFingerprintMask) {
    elChkFingerprintMask.addEventListener('change', (e) => {
      chrome.storage.local.set({ 'ctb_fingerprint_mask': e.target.checked });
    });
  }
  if (elChkOmniChain) {
    elChkOmniChain.addEventListener('change', (e) => {
      chrome.storage.local.set({ 'ctb_omni_reference_chaining': e.target.checked }, () => {
        updateOmniSliderUI(e.target.checked);
        chrome.tabs.query({ url: ['*://*.dola.com/*', '*://*.doubao.com/*'] }, (tabs) => {
          tabs.forEach(t => {
            if (t.id) {
              chrome.tabs.sendMessage(t.id, {
                type: 'SET_OMNI_CHAIN_CONFIG',
                enabled: e.target.checked
              }).catch(() => {});
            }
          });
        });
      });
    });
  }

  // 🔄 OMNI REFERENCE CLICK TO ATTACH (Studio Settings Card)
  const elBtnToggleOmni = document.getElementById('btn-toggle-omni-mode');
  const elOmniIndicator = document.getElementById('omni-slider-indicator');
  const elOmniLabel = document.getElementById('omni-slider-label');

  if (elBtnToggleOmni) {
    function resetOmniBtn() {
      if (elOmniLabel) elOmniLabel.textContent = '➕ Attach Last Frame';
      if (elOmniIndicator) {
        elOmniIndicator.style.background = '#c084fc';
        elOmniIndicator.style.boxShadow = '0 0 5px #c084fc';
      }
      elBtnToggleOmni.disabled = false;
    }

    elBtnToggleOmni.addEventListener('click', (e) => {
      e.preventDefault();
      elBtnToggleOmni.disabled = true;
      if (elOmniLabel) elOmniLabel.textContent = '⏳ Attaching...';
      if (elOmniIndicator) {
        elOmniIndicator.style.background = '#f59e0b';
        elOmniIndicator.style.boxShadow = '0 0 6px #f59e0b';
      }

      chrome.tabs.query({ active: true, currentWindow: true }, async (tabs) => {
        let activeTab = tabs && tabs[0];
        if (!activeTab || !activeTab.id || (!activeTab.url?.includes('dola.com') && !activeTab.url?.includes('doubao.com') && !activeTab.url?.includes('seaart.ai'))) {
          const dolaTabs = await new Promise(r => chrome.tabs.query({ url: ['*://*.dola.com/*', '*://dola.com/*', '*://*.doubao.com/*', '*://doubao.com/*', '*://*.seaart.ai/*'] }, r));
          if (dolaTabs && dolaTabs.length > 0) {
            activeTab = dolaTabs.find(t => t.active) || dolaTabs[0];
          }
        }
        if (!activeTab || !activeTab.id) {
          if (elOmniLabel) elOmniLabel.textContent = '❌ No Active Tab';
          setTimeout(resetOmniBtn, 2000);
          return;
        }

        chrome.tabs.sendMessage(activeTab.id, { type: 'TRIGGER_STAGE_OMNI_REF' }, (response) => {
          if (chrome.runtime.lastError || !response?.ok) {
            if (elOmniLabel) elOmniLabel.textContent = response?.message || '❌ Failed';
            if (elOmniIndicator) {
              elOmniIndicator.style.background = '#ef4444';
              elOmniIndicator.style.boxShadow = '0 0 6px #ef4444';
            }
          } else {
            if (elOmniLabel) elOmniLabel.textContent = '✅ Attached!';
            if (elOmniIndicator) {
              elOmniIndicator.style.background = '#4ade80';
              elOmniIndicator.style.boxShadow = '0 0 6px #4ade80';
            }
          }
          setTimeout(resetOmniBtn, 3000);
        });
      });
    });
  }

  // 🎬 VIDEO REFERENCE CLICK CONTROLLER
  const elBtnOpenVideoRef = document.getElementById('btn-open-video-ref');
  if (elBtnOpenVideoRef) {
    elBtnOpenVideoRef.addEventListener('click', (e) => {
      e.preventDefault();
      chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
        const activeTab = tabs && tabs[0];
        if (!activeTab || !activeTab.id) return;
        chrome.tabs.sendMessage(activeTab.id, { type: 'OPEN_VIDEO_REF_MODAL' }, { frameId: 0 }, () => {});
      });
    });
  }

  // 🏷️ SMART DOWNLOAD FILENAME FORMATTER CONTROLLER
  const elSelFilenamePreset = document.getElementById('sel-filename-preset');
  const elInputFilenamePattern = document.getElementById('input-filename-pattern');
  const elFilenamePreviewText = document.getElementById('filename-preview-text');
  const btnTagChips = document.querySelectorAll('.btn-tag-chip');

  function updateFilenamePreview(pattern) {
    if (!elFilenamePreviewText) return;
    const pat = pattern || '{prompt}_{duration}';
    let preview = pat
      .replace(/\{prompt\}/gi, 'Golden_Lotus_Goddess')
      .replace(/\{account\}/gi, 'Account_1')
      .replace(/\{date\}/gi, '2026-09-03')
      .replace(/\{time\}/gi, '13-45-00')
      .replace(/\{duration\}/gi, '30s_HD')
      .replace(/\{ratio\}/gi, '9x16')
      .replace(/\{resolution\}/gi, '1080P')
      .replace(/\{index\}/gi, '01')
      .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
      .replace(/\s+/g, '_')
      .replace(/_+/g, '_');
    elFilenamePreviewText.textContent = `${preview}.mp4`;
  }

  // Load saved pattern from storage
  chrome.storage.local.get(['zdola_auto_download_config'], (res) => {
    const cfg = res?.zdola_auto_download_config || {};
    const pat = cfg.filenamePattern || '{prompt}_{duration}';
    if (elInputFilenamePattern) elInputFilenamePattern.value = pat;
    if (elSelFilenamePreset) {
      const matchOpt = Array.from(elSelFilenamePreset.options).find(opt => opt.value === pat);
      elSelFilenamePreset.value = matchOpt ? pat : 'custom';
    }
    updateFilenamePreview(pat);
  });

  if (elSelFilenamePreset) {
    elSelFilenamePreset.addEventListener('change', (e) => {
      const val = e.target.value;
      if (val !== 'custom') {
        if (elInputFilenamePattern) elInputFilenamePattern.value = val;
        saveFilenamePattern(val);
      }
    });
  }

  if (elInputFilenamePattern) {
    elInputFilenamePattern.addEventListener('input', (e) => {
      const val = e.target.value;
      if (elSelFilenamePreset) {
        const matchOpt = Array.from(elSelFilenamePreset.options).find(opt => opt.value === val);
        elSelFilenamePreset.value = matchOpt ? val : 'custom';
      }
      saveFilenamePattern(val);
    });
  }

  btnTagChips.forEach(chip => {
    chip.addEventListener('click', () => {
      const tag = chip.getAttribute('data-tag');
      if (!elInputFilenamePattern || !tag) return;
      elInputFilenamePattern.value = (elInputFilenamePattern.value ? `${elInputFilenamePattern.value}_` : '') + tag;
      if (elSelFilenamePreset) elSelFilenamePreset.value = 'custom';
      saveFilenamePattern(elInputFilenamePattern.value);
    });
  });

  function saveFilenamePattern(pattern) {
    updateFilenamePreview(pattern);
    chrome.storage.local.get(['zdola_auto_download_config'], (res) => {
      const current = res?.zdola_auto_download_config || {};
      const updated = { ...current, filenamePattern: pattern };
      chrome.storage.local.set({ 'zdola_auto_download_config': updated }, () => {
        chrome.runtime.sendMessage({
          type: 'UPDATE_CONFIG',
          config: { filenamePattern: pattern }
        }).catch(() => {});
      });
    });
  }

  function isSupportedDolaUrl(u) {
    if (!u || typeof u !== 'string') return false;
    return u.includes('dola.com') || u.includes('doubao.com') || u.includes('seaart.ai') || u.includes('zdola.com');
  }

  // 🧹 Reset Session & Rate Limits Button
  const elBtnClearSession = document.getElementById('btn-clear-session');
  if (elBtnClearSession) {
    elBtnClearSession.addEventListener('click', () => {
      const origHtml = elBtnClearSession.innerHTML;
      elBtnClearSession.disabled = true;
      elBtnClearSession.innerHTML = '<span style="font-weight: 800; color: #38bdf8;">🧹 Resetting Session...</span>';
      chrome.runtime.sendMessage({ action: 'RESET_SESSION_AND_RATE_LIMITS' }, (res) => {
        elBtnClearSession.innerHTML = '<span style="font-weight: 800; color: #4ade80;">✅ Clean Session Ready!</span>';
        setTimeout(() => {
          elBtnClearSession.innerHTML = origHtml;
          elBtnClearSession.disabled = false;
        }, 2000);
      });
    });
  }

  // ============================================================================
  // 📦 ChannaTheBrand Bulk Download Mode & Auto-Scroll Suite
  // ============================================================================
  const elToggleBulkMode = document.getElementById('toggle-bulk-mode');
  const elChkBulkMode = document.getElementById('chk-bulk-mode');
  const elBtnScrollChatVideos = document.getElementById('btn-scroll-chat-videos');

  function syncBulkModeToggles(val) {
    if (elToggleBulkMode) elToggleBulkMode.checked = Boolean(val);
    if (elChkBulkMode) elChkBulkMode.checked = Boolean(val);
  }

  // Load initial bulk mode state
  try {
    chrome.storage.local.get(['channa_bulk_mode'], res => {
      syncBulkModeToggles(res?.channa_bulk_mode);
    });
  } catch (e) {}

  async function broadcastBulkMode(enabled) {
    syncBulkModeToggles(enabled);
    try {
      await chrome.storage.local.set({ channa_bulk_mode: Boolean(enabled) });
      const tabs = await chrome.tabs.query({});
      for (const tab of (tabs || [])) {
        if (!tab?.id) continue;
        const u = tab.url || '';
        if (u && (u.startsWith('chrome://') || u.startsWith('edge://') || u.startsWith('about:') || u.startsWith('chrome-extension://'))) {
          continue;
        }
        chrome.tabs.sendMessage(tab.id, { type: 'CHANNA_SET_BULK_MODE', enabled: Boolean(enabled) }, () => {
          void chrome.runtime.lastError;
        });
      }
    } catch (e) {}
  }

  if (elToggleBulkMode) {
    elToggleBulkMode.addEventListener('change', (e) => {
      broadcastBulkMode(e.target.checked);
    });
  }

  if (elChkBulkMode) {
    elChkBulkMode.addEventListener('change', (e) => {
      broadcastBulkMode(e.target.checked);
    });
  }

  if (elBtnScrollChatVideos) {
    elBtnScrollChatVideos.addEventListener('click', async () => {
      try {
        await broadcastBulkMode(true);
        const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
        let targetTab = activeTab;
        if (!targetTab || !isSupportedDolaUrl(targetTab.url)) {
          const dolaTabs = await chrome.tabs.query({ url: "*://*.dola.com/*" });
          targetTab = dolaTabs[0];
        }

        if (targetTab?.id) {
          chrome.tabs.sendMessage(targetTab.id, { type: 'CHANNA_START_CHAT_SCROLL' }, () => {
            void chrome.runtime.lastError;
          });

          const origHtml = elBtnScrollChatVideos.innerHTML;
          elBtnScrollChatVideos.innerHTML = `
            <span class="button-copy">
              <strong style="color: #4ade80;">📜 Auto-Scrolling Chat Upwards!</strong>
              <small style="color: #bbf7d0;">Harvesting past videos in active chat...</small>
            </span>
          `;
          setTimeout(() => {
            elBtnScrollChatVideos.innerHTML = origHtml;
          }, 3500);
        }
      } catch (err) {
        console.error('[ChannaTheBrand Auto-Scroll] Trigger error:', err);
      }
    });
  }

  const elBtnResetChatVideos = document.getElementById('btn-reset-chat-videos');
  if (elBtnResetChatVideos) {
    elBtnResetChatVideos.addEventListener('click', async () => {
      try {
        const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
        let targetTab = activeTab;
        if (!targetTab || !isSupportedDolaUrl(targetTab.url)) {
          const dolaTabs = await chrome.tabs.query({ url: "*://*.dola.com/*" });
          targetTab = dolaTabs[0];
        }

        if (targetTab?.id) {
          chrome.tabs.sendMessage(targetTab.id, { type: 'CHANNA_RESET_CHAT_VIDEOS' }, () => {
            void chrome.runtime.lastError;
          });

          const origHtml = elBtnResetChatVideos.innerHTML;
          elBtnResetChatVideos.innerHTML = `
            <strong style="font-size: 10px; color: #4ade80; line-height: 1.2;">✓ Done</strong>
            <small style="font-size: 7.5px; color: #86efac; line-height: 1;">Reset</small>
          `;
          setTimeout(() => {
            elBtnResetChatVideos.innerHTML = origHtml;
          }, 2000);
        }
      } catch (err) {
        console.error('[ChannaTheBrand Reset] Trigger error:', err);
      }
    });
  }

  console.log('[ChannaTheBrand Pro] ⚙️ Settings, Credit Limit & Omni-Ref Click Active.');
})();

// ============================================================================
// 🎭 CONSISTENT CHARACTER: ACTOR VAULT & CONTINUITY ENGINE (MUKAMMAL)
// ============================================================================
(() => {
  'use strict';

  // Elements
  const elBtnOpenActorVault = document.getElementById('btn-open-actor-vault');
  const elActorVaultLabel = document.getElementById('actor-vault-label');
  const elActorVaultIndicator = document.getElementById('actor-vault-indicator');
  const elModalActorVault = document.getElementById('modal-actor-vault');
  const elBtnCloseActorVault = document.getElementById('btn-close-actor-vault');

  // Active status elements
  const elActorActiveName = document.getElementById('actor-active-name');
  const elActorActiveDnaSnippet = document.getElementById('actor-active-dna-snippet');
  const elActorActiveEmptyIcon = document.getElementById('actor-active-empty-icon');
  const elActorActiveAvatarImg = document.getElementById('actor-active-avatar-img');
  const elBtnAttachActiveActor = document.getElementById('btn-attach-active-actor');
  const elBtnClearActiveActor = document.getElementById('btn-clear-active-actor');

  // Toggles
  const elChkActorAutoAttach = document.getElementById('chk-actor-auto-attach');
  const elChkActorAutoDna = document.getElementById('chk-actor-auto-dna');
  const elChkActorChainStory = document.getElementById('chk-actor-chain-story');

  // Form elements
  const elActorFormTitle = document.getElementById('actor-form-title');
  const elInputActorName = document.getElementById('input-actor-name');
  const elInputActorPhoto = document.getElementById('input-actor-photo');
  const elActorPreviewPlaceholder = document.getElementById('actor-preview-placeholder');
  const elActorPreviewImg = document.getElementById('actor-preview-img');
  const elBtnGrabChatFrame = document.getElementById('btn-grab-chat-frame');
  const elBtnRemoveActorPhoto = document.getElementById('btn-remove-actor-photo');
  const elInputActorDna = document.getElementById('input-actor-dna');
  const elBtnSaveActor = document.getElementById('btn-save-actor');
  const elBtnResetActorForm = document.getElementById('btn-reset-actor-form');
  const elActorVaultList = document.getElementById('actor-vault-list');
  const elActorVaultCountLabel = document.getElementById('actor-vault-count-label');
  const elBtnLoadSampleActors = document.getElementById('btn-load-sample-actors');

  let currentEditingActorId = null;
  let currentUploadedPhotoBase64 = '';

  function escapeHtml(str) {
    return String(str || '').replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  let vaultState = {
    activeCharacterId: null,
    autoAttachRef: true,
    autoInjectDNA: true,
    chainStoryMode: true,
    characters: []
  };

  function isDolaPage(url) {
    return typeof url === 'string' && (url.includes('dola.com') || url.includes('dola.ai') || url.includes('doubao.com') || url.includes('seaart.ai'));
  }

  // Load vault from storage
  function loadVault() {
    chrome.storage.local.get(['ctb_character_vault'], (res) => {
      const data = res?.ctb_character_vault;
      if (data && typeof data === 'object') {
        vaultState = {
          activeCharacterId: data.activeCharacterId || null,
          autoAttachRef: data.autoAttachRef !== false,
          autoInjectDNA: data.autoInjectDNA !== false,
          chainStoryMode: data.chainStoryMode !== false,
          characters: Array.isArray(data.characters) ? data.characters : []
        };
      } else {
        loadSamplePresets(false);
      }
      updateUI();
    });
  }

  // Save vault to storage
  function saveVault(callback) {
    chrome.storage.local.set({ ctb_character_vault: vaultState }, () => {
      updateUI();
      // Broadcast to tabs
      chrome.tabs.query({}, (tabs) => {
        tabs?.forEach(t => {
          if (isDolaPage(t.url)) {
            chrome.tabs.sendMessage(t.id, { type: 'CTB_SYNC_ACTOR_VAULT', vault: vaultState }, () => {
              void chrome.runtime.lastError;
            });
          }
        });
      });
      if (callback) callback();
    });
  }

  // Update UI components
  function updateUI() {
    if (elChkActorAutoAttach) elChkActorAutoAttach.checked = vaultState.autoAttachRef;
    if (elChkActorAutoDna) elChkActorAutoDna.checked = vaultState.autoInjectDNA;
    if (elChkActorChainStory) elChkActorChainStory.checked = vaultState.chainStoryMode;

    const activeActor = vaultState.characters.find(c => c.id === vaultState.activeCharacterId);
    if (activeActor) {
      if (elActorActiveName) elActorActiveName.textContent = activeActor.name;
      if (elActorActiveDnaSnippet) elActorActiveDnaSnippet.textContent = activeActor.dnaTokens || 'No DNA tokens defined';
      if (activeActor.avatarUrl && elActorActiveAvatarImg) {
        elActorActiveAvatarImg.src = activeActor.avatarUrl;
        elActorActiveAvatarImg.classList.remove('hidden');
        if (elActorActiveEmptyIcon) elActorActiveEmptyIcon.classList.add('hidden');
      } else {
        if (elActorActiveAvatarImg) {
          elActorActiveAvatarImg.removeAttribute('src');
          elActorActiveAvatarImg.classList.add('hidden');
        }
        if (elActorActiveEmptyIcon) elActorActiveEmptyIcon.classList.remove('hidden');
      }
      if (elBtnAttachActiveActor) elBtnAttachActiveActor.disabled = false;
      if (elBtnClearActiveActor) elBtnClearActiveActor.style.display = 'inline-block';

      if (elActorVaultLabel) elActorVaultLabel.textContent = `🎭 ${activeActor.name.split(' ')[0]}`;
      if (elActorVaultIndicator) {
        elActorVaultIndicator.style.background = '#4ade80';
        elActorVaultIndicator.style.boxShadow = '0 0 5px #4ade80';
      }
    } else {
      if (elActorActiveName) elActorActiveName.textContent = 'No Character Locked';
      if (elActorActiveDnaSnippet) elActorActiveDnaSnippet.textContent = 'Select or add a character below';
      if (elActorActiveAvatarImg) {
        elActorActiveAvatarImg.removeAttribute('src');
        elActorActiveAvatarImg.classList.add('hidden');
      }
      if (elActorActiveEmptyIcon) elActorActiveEmptyIcon.classList.remove('hidden');
      if (elBtnAttachActiveActor) elBtnAttachActiveActor.disabled = true;
      if (elBtnClearActiveActor) elBtnClearActiveActor.style.display = 'none';

      if (elActorVaultLabel) elActorVaultLabel.textContent = '🎭 Actor Vault';
      if (elActorVaultIndicator) {
        elActorVaultIndicator.style.background = '#f472b6';
        elActorVaultIndicator.style.boxShadow = '0 0 3px #f472b6';
      }
    }

    renderCharacterList();
  }

  // Render character list cards
  function renderCharacterList() {
    if (!elActorVaultList) return;
    const chars = vaultState.characters || [];
    if (elActorVaultCountLabel) elActorVaultCountLabel.textContent = `🎭 SAVED CHARACTERS (${chars.length})`;

    if (chars.length === 0) {
      elActorVaultList.innerHTML = `
        <div style="text-align: center; padding: 12px; color: #94a3b8; font-size: 8px;">
          No characters in vault yet.<br>Click "<strong>+ Add Sample Presets</strong>" above or create a new profile!
        </div>
      `;
      return;
    }

    elActorVaultList.innerHTML = '';
    chars.forEach(actor => {
      const isActive = actor.id === vaultState.activeCharacterId;
      const card = document.createElement('div');
      card.className = `actor-card${isActive ? ' active-actor' : ''}`;

      const avatarHtml = actor.avatarUrl
        ? `<img src="${actor.avatarUrl}" style="width: 28px; height: 28px; border-radius: 4px; object-fit: cover; border: 1px solid rgba(244, 114, 182, 0.4); display: block; flex-shrink: 0;" alt="${escapeHtml(actor.name || 'Actor')}" onerror="this.onerror=null; this.parentElement.innerHTML='<div style=\\'width: 28px; height: 28px; border-radius: 4px; background: rgba(30, 22, 56, 0.8); border: 1px solid rgba(244, 114, 182, 0.25); display: flex; align-items: center; justify-content: center; font-size: 11px; flex-shrink: 0;\\'>👤</div>';">`
        : `<div style="width: 28px; height: 28px; border-radius: 4px; background: rgba(30, 22, 56, 0.8); border: 1px solid rgba(244, 114, 182, 0.25); display: flex; align-items: center; justify-content: center; font-size: 11px; flex-shrink: 0;">👤</div>`;

      card.innerHTML = `
        <div style="display: flex; align-items: center; gap: 6px; min-width: 0; flex: 1;">
          ${avatarHtml}
          <div style="min-width: 0; flex: 1;">
            <div style="display: flex; align-items: center; gap: 4px;">
              <strong style="font-size: 9px; color: ${isActive ? '#f472b6' : '#ffffff'}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 110px;">${escapeHtml(actor.name || 'Unnamed')}</strong>
              ${isActive ? '<span style="font-size: 6.5px; background: rgba(52, 211, 153, 0.2); color: #34d399; border: 1px solid rgba(52, 211, 153, 0.4); padding: 0 3px; border-radius: 3px; font-weight: 800;">LOCKED</span>' : ''}
            </div>
            <div style="font-size: 7px; color: #94a3b8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 140px;" title="${escapeHtml(actor.dnaTokens || '')}">
              ${escapeHtml(actor.dnaTokens || 'No DNA tokens')}
            </div>
          </div>
        </div>
        <div style="display: flex; gap: 3px; align-items: center; flex-shrink: 0;">
          <button class="btn-lock-actor" data-id="${actor.id}" style="background: ${isActive ? 'rgba(52, 211, 153, 0.2)' : 'rgba(244, 114, 182, 0.2)'}; border: 1px solid ${isActive ? '#34d399' : '#f472b6'}; color: ${isActive ? '#34d399' : '#f472b6'}; border-radius: 4px; padding: 2px 5px; font-size: 7.5px; font-weight: 700; cursor: pointer;" title="${isActive ? 'Character currently locked' : 'Lock as active character'}">
            ${isActive ? '✓ Active' : '🔒 Lock'}
          </button>
          <button class="btn-stage-actor" data-id="${actor.id}" style="background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.35); color: #38bdf8; border-radius: 4px; padding: 2px 4px; font-size: 7.5px; font-weight: 700; cursor: pointer;" title="Attach photo to active Dola chat input">
            ⚡ Stage
          </button>
          <button class="btn-edit-actor" data-id="${actor.id}" style="background: rgba(168, 85, 247, 0.15); border: 1px solid rgba(168, 85, 247, 0.35); color: #c084fc; border-radius: 4px; padding: 2px 4px; font-size: 7.5px; cursor: pointer;" title="Edit profile">
            ✏️
          </button>
          <button class="btn-delete-actor" data-id="${actor.id}" style="background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.35); color: #f87171; border-radius: 4px; padding: 2px 4px; font-size: 7.5px; cursor: pointer;" title="Delete profile">
            🗑️
          </button>
        </div>
      `;

      elActorVaultList.appendChild(card);
    });
  }

  // Open & Close Modal
  if (elBtnOpenActorVault && elModalActorVault) {
    elBtnOpenActorVault.addEventListener('click', (e) => {
      e.preventDefault();
      loadVault();
      elModalActorVault.classList.remove('hidden');
    });
  }
  if (elBtnCloseActorVault && elModalActorVault) {
    elBtnCloseActorVault.addEventListener('click', () => {
      elModalActorVault.classList.add('hidden');
    });
  }

  // Toggle handlers
  if (elChkActorAutoAttach) {
    elChkActorAutoAttach.addEventListener('change', () => {
      vaultState.autoAttachRef = elChkActorAutoAttach.checked;
      saveVault();
    });
  }
  if (elChkActorAutoDna) {
    elChkActorAutoDna.addEventListener('change', () => {
      vaultState.autoInjectDNA = elChkActorAutoDna.checked;
      saveVault();
    });
  }
  if (elChkActorChainStory) {
    elChkActorChainStory.addEventListener('change', () => {
      vaultState.chainStoryMode = elChkActorChainStory.checked;
      saveVault();
    });
  }

  // Lock / Unlock Active
  if (elBtnClearActiveActor) {
    elBtnClearActiveActor.addEventListener('click', () => {
      vaultState.activeCharacterId = null;
      saveVault();
    });
  }

  // Attach active character to active tab
  if (elBtnAttachActiveActor) {
    elBtnAttachActiveActor.addEventListener('click', () => {
      const activeActor = vaultState.characters.find(c => c.id === vaultState.activeCharacterId);
      if (!activeActor) return;
      stageActorToActiveTab(activeActor, elBtnAttachActiveActor);
    });
  }

  // Stage character to composer in active Dola tab
  async function stageActorToActiveTab(actor, buttonEl) {
    if (!actor) return;
    try {
      const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
      let targetTab = activeTab;
      if (!targetTab || !isDolaPage(targetTab.url)) {
        const dolaTabs = await chrome.tabs.query({ url: "*://*.dola.com/*" });
        targetTab = dolaTabs[0];
      }
      if (!targetTab?.id) {
        alert('Please open or switch to a Dola AI chat tab first!');
        return;
      }

      if (buttonEl) {
        buttonEl.disabled = true;
        buttonEl.textContent = '⏳ Staging...';
      }

      chrome.tabs.sendMessage(targetTab.id, {
        type: 'STAGE_CHARACTER_ACTOR',
        actor: {
          id: actor.id,
          name: actor.name,
          avatarUrl: actor.avatarUrl || '',
          dnaTokens: actor.dnaTokens || ''
        }
      }, (res) => {
        void chrome.runtime.lastError;
        if (buttonEl) {
          buttonEl.disabled = false;
          buttonEl.textContent = res?.ok ? '✓ Staged to Chat!' : '⚡ Stage to Chat';
          setTimeout(() => {
            if (buttonEl) buttonEl.textContent = '⚡ Stage to Chat';
          }, 2500);
        }
      });
    } catch (err) {
      console.error('[Actor Vault] Stage error:', err);
      if (buttonEl) {
        buttonEl.disabled = false;
        buttonEl.textContent = '⚡ Stage to Chat';
      }
    }
  }

  const elBtnToggleNewActor = document.getElementById('btn-toggle-new-actor-form');
  if (elBtnToggleNewActor) {
    elBtnToggleNewActor.addEventListener('click', () => {
      resetForm();
      const formCard = document.getElementById('actor-form-card');
      if (formCard) formCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
      elInputActorName?.focus();
    });
  }

  // Photo Upload Handler (Resizes image to max 512x512 JPEG)
  if (elInputActorPhoto) {
    elInputActorPhoto.addEventListener('change', (e) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (re) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let w = img.width;
          let h = img.height;
          const maxDim = 512;
          if (w > maxDim || h > maxDim) {
            if (w > h) {
              h = Math.round((h * maxDim) / w);
              w = maxDim;
            } else {
              w = Math.round((w * maxDim) / h);
              h = maxDim;
            }
          }
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          currentUploadedPhotoBase64 = canvas.toDataURL('image/jpeg', 0.88);
          setPhotoPreview(currentUploadedPhotoBase64);
        };
        img.src = re.target.result;
      };
      reader.readAsDataURL(file);
    });
  }

  // Grab Current Video Frame from Chat
  if (elBtnGrabChatFrame) {
    elBtnGrabChatFrame.addEventListener('click', async () => {
      try {
        const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
        let targetTab = activeTab;
        if (!targetTab || !isDolaPage(targetTab.url)) {
          const dolaTabs = await chrome.tabs.query({ url: "*://*.dola.com/*" });
          targetTab = dolaTabs[0];
        }
        if (!targetTab?.id) {
          alert('Please open or focus a Dola AI chat tab with generated videos first!');
          return;
        }

        const origHtml = elBtnGrabChatFrame.innerHTML;
        elBtnGrabChatFrame.disabled = true;
        elBtnGrabChatFrame.textContent = '⏳ Grabbing...';

        chrome.tabs.sendMessage(targetTab.id, { type: 'GRAB_CHAT_VIDEO_FRAME' }, (res) => {
          void chrome.runtime.lastError;
          elBtnGrabChatFrame.disabled = false;
          elBtnGrabChatFrame.innerHTML = origHtml;

          if (res && res.ok && res.dataUrl) {
            currentUploadedPhotoBase64 = res.dataUrl;
            setPhotoPreview(currentUploadedPhotoBase64);
          } else {
            alert(res?.error || 'No active video found in the current Dola chat to grab a frame from.');
          }
        });
      } catch (err) {
        console.error('[Actor Vault] Frame grab error:', err);
        elBtnGrabChatFrame.disabled = false;
      }
    });
  }

  function setPhotoPreview(dataUrl) {
    if (dataUrl && elActorPreviewImg) {
      elActorPreviewImg.src = dataUrl;
      elActorPreviewImg.classList.remove('hidden');
      if (elActorPreviewPlaceholder) elActorPreviewPlaceholder.classList.add('hidden');
      if (elBtnRemoveActorPhoto) elBtnRemoveActorPhoto.classList.remove('hidden');
    } else {
      if (elActorPreviewImg) {
        elActorPreviewImg.removeAttribute('src');
        elActorPreviewImg.classList.add('hidden');
      }
      if (elActorPreviewPlaceholder) elActorPreviewPlaceholder.classList.remove('hidden');
      if (elBtnRemoveActorPhoto) elBtnRemoveActorPhoto.classList.add('hidden');
      currentUploadedPhotoBase64 = '';
      if (elInputActorPhoto) elInputActorPhoto.value = '';
    }
  }

  if (elBtnRemoveActorPhoto) {
    elBtnRemoveActorPhoto.addEventListener('click', () => {
      setPhotoPreview('');
    });
  }

  // Quick DNA Tag Chips
  document.querySelectorAll('.btn-dna-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const tag = chip.dataset.tag;
      if (!tag || !elInputActorDna) return;
      const current = elInputActorDna.value.trim();
      if (!current) {
        elInputActorDna.value = tag;
      } else if (!current.includes(tag)) {
        elInputActorDna.value = `${current}, ${tag}`;
      }
      elInputActorDna.focus();
    });
  });

  if (elBtnResetActorForm) {
    elBtnResetActorForm.addEventListener('click', () => {
      resetForm();
    });
  }

  function resetForm() {
    currentEditingActorId = null;
    currentUploadedPhotoBase64 = '';
    if (elInputActorName) elInputActorName.value = '';
    if (elInputActorDna) elInputActorDna.value = '';
    if (elActorFormTitle) elActorFormTitle.textContent = '➕ NEW CHARACTER PROFILE';
    if (elBtnSaveActor) elBtnSaveActor.textContent = '💾 Save Character to Vault';
    setPhotoPreview('');
  }

  // Save Actor Button
  if (elBtnSaveActor) {
    elBtnSaveActor.addEventListener('click', () => {
      const name = (elInputActorName?.value || '').trim();
      const dnaTokens = (elInputActorDna?.value || '').trim();

      if (!name) {
        alert('Please enter a Character Name!');
        elInputActorName?.focus();
        return;
      }

      if (currentEditingActorId) {
        const idx = vaultState.characters.findIndex(c => c.id === currentEditingActorId);
        if (idx !== -1) {
          vaultState.characters[idx].name = name;
          vaultState.characters[idx].dnaTokens = dnaTokens;
          if (currentUploadedPhotoBase64) {
            vaultState.characters[idx].avatarUrl = currentUploadedPhotoBase64;
          }
        }
      } else {
        const newActor = {
          id: `actor_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
          name: name,
          avatarUrl: currentUploadedPhotoBase64 || '',
          dnaTokens: dnaTokens,
          created: Date.now()
        };
        vaultState.characters.unshift(newActor);
        if (!vaultState.activeCharacterId) {
          vaultState.activeCharacterId = newActor.id;
        }
      }

      saveVault(() => {
        resetForm();
      });
    });
  }

  // Delegated clicks for List Cards
  if (elActorVaultList) {
    elActorVaultList.addEventListener('click', (e) => {
      // 1. Lock Active
      const lockBtn = e.target.closest('.btn-lock-actor');
      if (lockBtn) {
        const id = lockBtn.dataset.id;
        vaultState.activeCharacterId = vaultState.activeCharacterId === id ? null : id;
        saveVault();
        return;
      }

      // 2. Stage to Chat
      const stageBtn = e.target.closest('.btn-stage-actor');
      if (stageBtn) {
        const id = stageBtn.dataset.id;
        const actor = vaultState.characters.find(c => c.id === id);
        if (actor) stageActorToActiveTab(actor, stageBtn);
        return;
      }

      // 3. Edit Profile
      const editBtn = e.target.closest('.btn-edit-actor');
      if (editBtn) {
        const id = editBtn.dataset.id;
        const actor = vaultState.characters.find(c => c.id === id);
        if (actor) {
          currentEditingActorId = actor.id;
          if (elInputActorName) elInputActorName.value = actor.name;
          if (elInputActorDna) elInputActorDna.value = actor.dnaTokens || '';
          if (elActorFormTitle) elActorFormTitle.textContent = `✏️ EDIT: ${actor.name}`;
          if (elBtnSaveActor) elBtnSaveActor.textContent = '💾 Update Character Profile';
          if (actor.avatarUrl) {
            currentUploadedPhotoBase64 = actor.avatarUrl;
            setPhotoPreview(actor.avatarUrl);
          } else {
            setPhotoPreview('');
          }
          elInputActorName?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        return;
      }

      // 4. Delete Profile
      const deleteBtn = e.target.closest('.btn-delete-actor');
      if (deleteBtn) {
        const id = deleteBtn.dataset.id;
        const actor = vaultState.characters.find(c => c.id === id);
        if (confirm(`Delete character "${actor?.name || 'this character'}" from vault?`)) {
          vaultState.characters = vaultState.characters.filter(c => c.id !== id);
          if (vaultState.activeCharacterId === id) {
            vaultState.activeCharacterId = null;
          }
          saveVault();
        }
        return;
      }
    });
  }

  // Sample Presets Loader
  if (elBtnLoadSampleActors) {
    elBtnLoadSampleActors.addEventListener('click', () => {
      loadSamplePresets(true);
    });
  }

  function loadSamplePresets(overwrite = false) {
    const samples = [
      {
        id: 'actor_sample_sarah',
        name: 'Sarah (Cyberpunk)',
        avatarUrl: '',
        dnaTokens: '26yo athletic woman, sharp cheekbones, emerald green eyes, black high ponytail, glowing neon purple cyber jacket, subtle eyebrow scar, cinematic lighting, ultra-realistic skin texture',
        created: Date.now()
      },
      {
        id: 'actor_sample_marcus',
        name: 'Marcus (Nordic Warrior)',
        avatarUrl: '',
        dnaTokens: '32yo rugged Nordic warrior, strong jawline, icy blue eyes, undercut braided dark blonde hair, textured leather fur armor, weathered skin, dramatic rim lighting, photorealistic 8k',
        created: Date.now() - 1000
      },
      {
        id: 'actor_sample_mei',
        name: 'Mei (Anime Heroine)',
        avatarUrl: '',
        dnaTokens: '19yo cute anime girl, large luminous violet eyes, twin tail silver hair, oversized pastel streetwear hoodie, studio anime style, hyper-detailed anime aesthetic, vibrant colors',
        created: Date.now() - 2000
      }
    ];

    if (!Array.isArray(vaultState.characters)) vaultState.characters = [];
    samples.forEach(s => {
      if (!vaultState.characters.some(c => c.id === s.id)) {
        vaultState.characters.push(s);
      }
    });
    if (!vaultState.activeCharacterId && vaultState.characters.length > 0) {
      vaultState.activeCharacterId = vaultState.characters[0].id;
    }
    saveVault();
  }

  loadVault();
})();

